# Next.js API Route Optimization

## Problem
Sequential `await` calls in API routes and server components cause waterfall delays. Each call waits for the previous one to complete before starting.

## Pattern: Sequential (Slow)
```typescript
// BAD: Each call waits for the previous one
export async function GET() {
  const user = await fetchUser();        // ~200ms
  const products = await fetchProducts(); // ~200ms (starts at 200ms)
  const reviews = await fetchReviews();   // ~200ms (starts at 400ms)
  // Total: ~600ms
}
```

## Pattern: Parallel with Promise.all (Fast)
```typescript
// GOOD: All calls start simultaneously
export async function GET() {
  const [user, products, reviews] = await Promise.all([
    fetchUser(),       // ~200ms
    fetchProducts(),   // ~200ms (starts at 0ms)
    fetchReviews(),    // ~200ms (starts at 0ms)
  ]);
  // Total: ~200ms
}
```

## Pattern: Non-blocking fire-and-forget for analytics
```typescript
// Analytics/logging should not block the response
export async function GET() {
  const [user, products] = await Promise.all([
    fetchUser(),
    fetchProducts(),
  ]);

  // Fire and forget - don't await analytics
  logAnalytics({ userId: user.id, action: 'view' }).catch(console.error);

  return NextResponse.json({ products });
}
```

## Pattern: Dependent calls after parallel independent calls
```typescript
// When some calls depend on results of others
export async function POST() {
  // Step 1: Run independent calls in parallel
  const [user, config] = await Promise.all([
    fetchUser(),
    fetchConfig(),
  ]);

  // Step 2: Dependent call (needs user.id) - can also be parallelized with config
  // Better: include profile in Promise.all if possible
  const profile = await fetchProfile(user.id);

  return NextResponse.json({ user, profile, config });
}
```

## Server Component Optimization
```typescript
// In Next.js server components, parallelize data fetching
export default async function Page() {
  const [user, products, reviews] = await Promise.all([
    fetchUser(),
    fetchProducts(),
    fetchReviews(),
  ]);

  return <Component user={user} products={products} reviews={reviews} />;
}
```

## Key Rules
1. Use `Promise.all()` for independent async calls
2. Never `await` analytics/logging that doesn't affect the response
3. Only sequentialize calls that have data dependencies
4. Consider `Promise.allSettled()` when partial failures are acceptable

# React Rendering Optimization

## Problem
Unnecessary re-renders cause slow interactions. When parent state changes (e.g., adding to cart), all child components re-render even if their props haven't changed.

## React.memo - Prevent unnecessary re-renders
```typescript
// Wrap component to skip re-renders when props haven't changed
import { memo } from 'react';

export const ProductCard = memo(function ProductCard({ product, onAddToCart, isInCart }: Props) {
  performance.mark(`ProductCard-render-${product.id}`);
  return (
    <div>
      {/* component content */}
    </div>
  );
});
```

## useCallback - Stabilize function references
```typescript
// Without useCallback, a new function is created every render,
// defeating React.memo on child components
import { useCallback } from 'react';

function ProductList() {
  const [cart, setCart] = useState<string[]>([]);

  // BAD: new function every render
  const handleAddToCart = (id: string) => setCart(prev => [...prev, id]);

  // GOOD: stable function reference
  const handleAddToCart = useCallback((id: string) => {
    setCart(prev => [...prev, id]);
  }, []);

  return <ProductCard onAddToCart={handleAddToCart} />;
}
```

## useMemo - Cache expensive computations
```typescript
import { useMemo } from 'react';

function ProductList({ products, reviews }: Props) {
  const [filter, setFilter] = useState('');
  const [sortBy, setSortBy] = useState<'price' | 'rating'>('price');

  // Pre-compute review counts once (instead of O(n*m) per render)
  const reviewCountMap = useMemo(() => {
    const map: Record<string, number> = {};
    reviews.forEach(r => {
      map[r.productId] = (map[r.productId] || 0) + 1;
    });
    return map;
  }, [reviews]);

  // Memoize filtered/sorted products
  const filteredProducts = useMemo(() => {
    return products
      .filter(p => p.name.toLowerCase().includes(filter.toLowerCase()))
      .filter(p => p.inStock)
      .sort((a, b) => sortBy === 'price' ? a.price - b.price : b.rating - a.rating);
  }, [products, filter, sortBy]);

  return (
    <div>
      {filteredProducts.map(p => (
        <ProductCard
          key={p.id}
          reviewCount={reviewCountMap[p.id] || 0}
        />
      ))}
    </div>
  );
}
```

## Key Rules
1. Use `React.memo` on components that receive the same props frequently
2. Use `useCallback` for handler functions passed to memoized children
3. Use `useMemo` for expensive computations (filtering, sorting, lookups)
4. Pre-compute lookup maps (O(n)) instead of filtering inside loops (O(n*m))
5. Never remove `performance.mark()` calls - they are for monitoring

# Next.js Bundle Size Reduction

## Problem
Large libraries like `lodash` (5MB) and `mathjs` (18MB) dramatically increase bundle size and page load time, especially when only a few functions are used.

## Strategy 1: Replace with Native JavaScript

### Replacing lodash functions
```typescript
// lodash sortBy -> native
const sorted = [...arr].sort((a, b) => a.price - b.price);

// lodash meanBy -> native
const mean = arr.reduce((sum, item) => sum + item.price, 0) / arr.length;

// lodash sumBy -> native
const sum = arr.reduce((total, item) => total + item.reviews, 0);

// lodash maxBy -> native
const max = arr.reduce((best, item) => item.rating > best.rating ? item : best);

// lodash minBy -> native
const min = arr.reduce((best, item) => item.price < best.price ? item : best);
```

### Replacing mathjs functions
```typescript
// mean
const mean = (nums: number[]) => nums.reduce((a, b) => a + b, 0) / nums.length;

// median
const median = (nums: number[]) => {
  const sorted = [...nums].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
};

// standard deviation
const std = (nums: number[]) => {
  const avg = mean(nums);
  return Math.sqrt(nums.reduce((sum, n) => sum + (n - avg) ** 2, 0) / nums.length);
};

// variance
const variance = (nums: number[]) => {
  const avg = mean(nums);
  return nums.reduce((sum, n) => sum + (n - avg) ** 2, 0) / nums.length;
};

// quantile
const quantile = (nums: number[], q: number) => {
  const sorted = [...nums].sort((a, b) => a - b);
  const pos = (sorted.length - 1) * q;
  const base = Math.floor(pos);
  const rest = pos - base;
  if (sorted[base + 1] !== undefined) {
    return sorted[base] + rest * (sorted[base + 1] - sorted[base]);
  }
  return sorted[base];
};
```

## Strategy 2: Dynamic Imports (next/dynamic)
When a component uses a heavy library but isn't always visible (e.g., tab content):

```typescript
import dynamic from 'next/dynamic';

// Lazy load component - only downloads when rendered
const AdvancedAnalysis = dynamic(() => import('./AdvancedAnalysis'), {
  loading: () => <p>Loading analysis...</p>,
});

// Usage - component code only loaded when tab is active
{activeTab === 'advanced' && <AdvancedAnalysis products={products} />}
```

## Strategy 3: Tree-shakeable imports
If you must use lodash, import individual functions:
```typescript
// BAD: imports entire lodash (5MB)
import { sortBy } from 'lodash';

// BETTER: imports only sortBy (~2KB)
import sortBy from 'lodash/sortBy';
```

## Key Rules
1. For 5 items of data, native JS is faster than any library
2. Eliminate lodash and mathjs when native alternatives are simple
3. Use `next/dynamic` for components not visible on initial render
4. Configure next.config.js to optimize imports if keeping libraries

# Next.js Dynamic Imports for Code Splitting

## Problem
Components with heavy dependencies load even when not visible. On a tabbed interface, all tab content loads upfront, increasing initial bundle size.

## Solution: next/dynamic
```typescript
import dynamic from 'next/dynamic';

// Lazy-load component - its code is in a separate chunk
const HeavyComponent = dynamic(() => import('./HeavyComponent'), {
  loading: () => <div className="animate-pulse bg-gray-200 h-64 rounded-xl" />,
});
```

## Pattern: Tab-based lazy loading
```typescript
'use client';
import { useState } from 'react';
import dynamic from 'next/dynamic';

// Only loaded when Advanced tab is clicked
const AdvancedAnalysis = dynamic(() =>
  import('./AdvancedAnalysis').then(mod => ({ default: mod.AdvancedAnalysis })),
  { loading: () => <div>Loading...</div> }
);

export default function ComparePage() {
  const [activeTab, setActiveTab] = useState<'overview' | 'advanced'>('overview');

  return (
    <div>
      <button onClick={() => setActiveTab('overview')}>Overview</button>
      <button onClick={() => setActiveTab('advanced')}>Advanced</button>

      {activeTab === 'overview' ? (
        <OverviewTable />
      ) : (
        <AdvancedAnalysis products={products} />
      )}
    </div>
  );
}
```

## When to use dynamic imports
- Tab content not visible on initial load
- Modal/dialog content
- Below-the-fold components
- Components using large third-party libraries
- Admin-only features

## Key rules
1. Always provide a `loading` fallback component
2. Don't dynamically import above-the-fold content
3. Combine with library replacement for maximum impact
4. Use `ssr: false` only when the component truly can't server-render

# Native JavaScript Statistics Utilities

## Purpose
Replace heavy math libraries (mathjs ~18MB) with lightweight native implementations for basic statistical functions.

## Implementations

### Mean (Average)
```typescript
function mean(nums: number[]): number {
  return nums.reduce((sum, n) => sum + n, 0) / nums.length;
}
```

### Median
```typescript
function median(nums: number[]): number {
  const sorted = [...nums].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0
    ? sorted[mid]
    : (sorted[mid - 1] + sorted[mid]) / 2;
}
```

### Standard Deviation (population)
```typescript
function std(nums: number[]): number {
  const avg = mean(nums);
  const squareDiffs = nums.map(n => (n - avg) ** 2);
  return Math.sqrt(squareDiffs.reduce((sum, d) => sum + d, 0) / nums.length);
}
```

### Variance (population)
```typescript
function variance(nums: number[]): number {
  const avg = mean(nums);
  return nums.reduce((sum, n) => sum + (n - avg) ** 2, 0) / nums.length;
}
```

### Quantile (linear interpolation)
```typescript
function quantile(nums: number[], q: number): number {
  const sorted = [...nums].sort((a, b) => a - b);
  const pos = (sorted.length - 1) * q;
  const base = Math.floor(pos);
  const rest = pos - base;
  if (sorted[base + 1] !== undefined) {
    return sorted[base] + rest * (sorted[base + 1] - sorted[base]);
  }
  return sorted[base];
}
```

## Usage Example
```typescript
const prices = [299.99, 149.99, 449.99, 79.99, 379.99];

const stats = {
  mean: mean(prices),           // 271.99
  median: median(prices),       // 299.99
  std: std(prices),             // ~131.57
  variance: variance(prices),   // ~17311.60
  q1: quantile(prices, 0.25),   // 149.99
  q3: quantile(prices, 0.75),   // 379.99
};
```

## Notes
- These implementations use population statistics (dividing by N, not N-1)
- mathjs `std()` and `variance()` by default use "unbiased" (sample) statistics (dividing by N-1)
- For consistency with mathjs defaults, use `(nums.length - 1)` as divisor if needed
- For small datasets (5 items), the difference is negligible for display purposes

